window.__votdWeek && window.__votdWeek({"week":"2028-11-06","reading":"Ether 1–5","days":[{"d":"2028-11-06","ref":"Ether 1:1","b":"Ether","c":1,"v":1,"he":"וְעַתָּה אֲנִי מוֹרוֹנִי פֹּנֶה לָתֵת אֶת־דִּבְרֵי הַיּוֹשְׁבִים הַקַּדְמוֹנִים הָהֵם אֲשֶׁר הֻשְׁמְדוּ בְּיַד־יְהוָה עַל־פְּנֵי הָאָרֶץ הַצְּפוֹנִית הַזֹּאת׃","en":"And now I, Moroni, proceed to give an account of those ancient inhabitants who were destroyed by the hand of the Lord upon the face of this north country."},{"d":"2028-11-07","ref":"Ether 1:42","b":"Ether","c":1,"v":42,"he":"וְכַאֲשֶׁר תַּעֲשֶׂה זֹאת תֵּלֵךְ בְּרֹאשָׁם אֶל־הָעֵמֶק אֲשֶׁר צָפוֹנָה וְשָׁם אֶפָּגֵשׁ עִמְּךָ וְאֵלֵךְ לְפָנֶיךָ אֶל־אֶרֶץ נִבְחֶרֶת מִכׇּל־אַרְצוֹת הָאָרֶץ׃","en":"And when thou hast done this thou shalt go at the head of them down into the valley which is northward. And there will I meet thee, and I will go before thee into a land which is choice above all the lands of the earth."},{"d":"2028-11-08","ref":"Ether 3:15","b":"Ether","c":3,"v":15,"he":"וּמֵעוֹלָם לֹא נִרְאֵיתִי לְאָדָם אֲשֶׁר בָּרָאתִי כִּי מֵעוֹלָם לֹא־הֶאֱמִין בִּי אָדָם כַּאֲשֶׁר הֶאֱמַנְתָּ הֲרָאִיתָ כִּי נִבְרֵאתָ בְּצַלְמִי אַף כׇּל־בְּנֵי הָאָדָם נִבְרְאוּ בָרִאשׁוֹנָה בְּצַלְמִי׃","en":"And never have I showed myself unto man whom I have created, for never has man believed in me as thou hast. Seest thou that ye are created after mine own image? Yea, even all men were created in the beginning after mine own image."},{"d":"2028-11-09","ref":"Ether 3:25","b":"Ether","c":3,"v":25,"he":"וַיְהִי כַּאֲשֶׁר דִּבֶּר יְהוָה אֶת־הַדְּבָרִים הָאֵלֶּה וַיַּרְאֵהוּ לַאֲחִי יֶרֶד אֶת־כׇּל־יוֹשְׁבֵי הָאָרֶץ אֲשֶׁר הָיוּ וְגַם אֶת־כׇּל־אֲשֶׁר יִהְיוּ וְלֹא מָנַע אוֹתָם מֵעֵינָיו עַד־קְצוֹת הָאָרֶץ׃","en":"And when the Lord had said these words, he showed unto the brother of Jared all the inhabitants of the earth which had been, and also all that would be; and he withheld them not from his sight, even unto the ends of the earth."},{"d":"2028-11-10","ref":"Ether 4:8","b":"Ether","c":4,"v":8,"he":"וְהַמִּתְוַכֵּחַ נֶגֶד דְּבַר־יְהוָה יוּאָר וְהַמְּכַחֵשׁ בַּדְּבָרִים הָאֵלֶּה יוּאָר כִּי לָהֶם לֹא אַרְאֶה דְּבָרִים גְּדוֹלִים מֵאֵלֶּה נְאֻם יֵשׁוּעַ הַמָּשִׁיחַ כִּי־אֲנִי הוּא הַמְּדַבֵּר׃","en":"And he that will contend against the word of the Lord, let him be accursed; and he that shall deny these things, let him be accursed; for unto them will I show no greater things, saith Jesus Christ; for I am he who speaketh."},{"d":"2028-11-11","ref":"Ether 4:19","b":"Ether","c":4,"v":19,"he":"וְאַשְׁרֵי הַנִּמְצָא נֶאֱמָן לִשְׁמִי בַּיּוֹם הָאַחֲרוֹן כִּי יִנָּשֵׂא לָשֶׁבֶת בַּמַּמְלָכָה הַמּוּכָנָה לוֹ מִמּוֹסְדוֹת תֵּבֵל וְהִנֵּה אֲנִי־הוּא הַמְדַבֵּר אָמֵן׃","en":"And blessed is he that is found faithful unto my name at the last day, for he shall be lifted up to dwell in the kingdom prepared for him from the foundation of the world. And behold it is I that hath spoken it. Amen."},{"d":"2028-11-12","ref":"Ether 5:3","b":"Ether","c":5,"v":3,"he":"וְלִשְׁלֹשָׁה יֵרָאוּ בִּגְבוּרַת אֱלֹהִים לָכֵן יֵדְעוּ בֶּאֱמֶת כִּי אֱמֶת הַדְּבָרִים הָאֵלֶּה׃","en":"And unto three shall they be shown by the power of God; wherefore they shall know of a surety that these things are true."}]});
